package main

import (
	"encoding/hex"
	"testing"
)

// Expected bytes generated by running the original Python implementation
// (thermobeacon_bridge.encode_ruuvi_rawv2 / build_udp_packet).
func TestEncodeRuuviRAWv2(t *testing.T) {
	r := &Reading{
		MAC:         "db:5c:8d:a0:0f:21",
		Temperature: 19.25,
		Humidity:    58.0,
		VoltageMV:   2880,
		Uptime:      2131727,
	}
	got, err := encodeRuuviRAWv2(r, 2131727&0xFFFF)
	if err != nil {
		t.Fatalf("encode: %v", err)
	}
	want := "050f0a5aa0ffff800080008000a01fff870fdb5c8da00f21"
	if hex.EncodeToString(got) != want {
		t.Errorf("RAWv2 = %s, want %s", hex.EncodeToString(got), want)
	}
}

// dbus-ble-sensors treats the raw battery value 0x3FF as invalid - the
// original works around this by sending 0x3FE instead.
func TestEncodeRuuviRAWv2BatteryWorkaround(t *testing.T) {
	r := &Reading{
		MAC:         "01:02:03:04:05:06",
		Temperature: -5.5,
		Humidity:    100.0,
		VoltageMV:   2623, // batt = 1023 = 0x3FF -> must be sent as 0x3FE
	}
	got, err := encodeRuuviRAWv2(r, 1)
	if err != nil {
		t.Fatalf("encode: %v", err)
	}
	want := "05fbb49c40ffff8000800080007fdfff0001010203040506"
	if hex.EncodeToString(got) != want {
		t.Errorf("RAWv2 = %s, want %s", hex.EncodeToString(got), want)
	}
}

func TestEncodeRuuviRAWv2Clamping(t *testing.T) {
	r := &Reading{
		MAC:         "aa:bb:cc:dd:ee:ff",
		Temperature: -999.0, // clamped to -163.835 degC
		Humidity:    250.0,  // clamped to 100 %
		VoltageMV:   4000,   // clamped to 3.646 V
	}
	got, err := encodeRuuviRAWv2(r, 0xFFFF)
	if err != nil {
		t.Fatalf("encode: %v", err)
	}
	want := "0580019c40ffff800080008000ffdfffffffaabbccddeeff"
	if hex.EncodeToString(got) != want {
		t.Errorf("RAWv2 = %s, want %s", hex.EncodeToString(got), want)
	}
}

func TestEncodeRuuviRAWv2Zeros(t *testing.T) {
	r := &Reading{MAC: "ff:ff:ff:ff:ff:ff", VoltageMV: 1600}
	got, err := encodeRuuviRAWv2(r, 0)
	if err != nil {
		t.Fatalf("encode: %v", err)
	}
	want := "0500000000ffff800080008000001fff0000ffffffffffff"
	if hex.EncodeToString(got) != want {
		t.Errorf("RAWv2 = %s, want %s", hex.EncodeToString(got), want)
	}
}

func TestEncodeRuuviRAWv2InvalidMAC(t *testing.T) {
	r := &Reading{MAC: "not-a-mac"}
	if _, err := encodeRuuviRAWv2(r, 0); err == nil {
		t.Error("invalid MAC accepted")
	}
}

func TestBuildUDPPacket(t *testing.T) {
	payload := mustHex("050f0a5aa0ffff800080008000a01fff870fdb5c8da00f21")
	got, err := buildUDPPacket("db:5c:8d:a0:0f:21", ruuviManufacturerID, payload, -52)
	if err != nil {
		t.Fatalf("buildUDPPacket: %v", err)
	}
	want := "0101210fa08d5cdb990418050f0a5aa0ffff800080008000a01fff870fdb5c8da00f21cc"
	if hex.EncodeToString(got) != want {
		t.Errorf("UDP packet = %s, want %s", hex.EncodeToString(got), want)
	}
}

func TestBuildUDPPacketInvalidMAC(t *testing.T) {
	if _, err := buildUDPPacket("nope", ruuviManufacturerID, make([]byte, 24), 0); err == nil {
		t.Error("invalid MAC accepted")
	}
}
